export const oauthappUpdateApp = <ThrowOnError extends boolean = false>(options: Options<OauthappUpdateAppData, ThrowOnError>): RequestResult<OauthappUpdateAppResponses, OauthappUpdateAppErrors, ThrowOnError> => (options.client ?? client).patch<OauthappUpdateAppResponses, OauthappUpdateAppErrors, ThrowOnError>({
    security: [{
            key: 'I18nJWTAuth',
            scheme: 'bearer',
            type: 'http'
        }],
    url: '/api/oauth/apps/{app_id}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

