export const oauthappUploadLogo = <ThrowOnError extends boolean = false>(options: Options<OauthappUploadLogoData, ThrowOnError>): RequestResult<OauthappUploadLogoResponses, OauthappUploadLogoErrors, ThrowOnError> => (options.client ?? client).post<OauthappUploadLogoResponses, OauthappUploadLogoErrors, ThrowOnError>({
    ...formDataBodySerializer,
    security: [{
            key: 'I18nJWTAuth',
            scheme: 'bearer',
            type: 'http'
        }],
    url: '/api/oauth/apps/{app_id}/logo',
    ...options,
    headers: {
        'Content-Type': null,
        ...options.headers
    }
});

