/**
 * Revoke
 *
 * Disconnect an app: every token, ID token and pending code you granted it dies.
 *
 * Both halves matter. ``authorize_service.has_prior_grant`` auto-approves the next
 * authorization request when *either* a live access token or an unrevoked refresh token
 * survives, so a partial revoke would hand the app a fresh grant with no consent screen
 * (R-78); ``token_service`` is what makes this complete.
 */
export const oauthconnectionRevoke = <ThrowOnError extends boolean = false>(options: Options<OauthconnectionRevokeData, ThrowOnError>): RequestResult<OauthconnectionRevokeResponses, OauthconnectionRevokeErrors, ThrowOnError> => (options.client ?? client).delete<OauthconnectionRevokeResponses, OauthconnectionRevokeErrors, ThrowOnError>({
    security: [{
            key: 'I18nJWTAuth',
            scheme: 'bearer',
            type: 'http'
        }],
    url: '/api/oauth/connections/{client_id}',
    ...options
});

